"use client";
import { useEffect, useRef, useState } from "react";
import { StorefrontBrandSculpture, type LogoMount } from "./storefront-brand-sculpture";
import type { HeroDepth } from "./dimensional-storefront-hero";
export function Storefront3DStudio({name,logo,edgeColor,initialMount,initialDepth,onApply,onClose,invitation=false,initialBrief,onBriefChange}:{name:string;logo:string;edgeColor:string;initialMount:LogoMount;initialDepth:HeroDepth;onApply:(depth:HeroDepth,mount:LogoMount)=>void;onClose:()=>void;invitation?:boolean;initialBrief:string;onBriefChange:(brief:string)=>void}) {
 const dialog=useRef<HTMLDialogElement>(null);
 const [intro,setIntro]=useState(invitation),[mode,setMode]=useState<'suggest'|'describe'>('suggest'),[brief,setBrief]=useState(initialBrief),[mount,setMount]=useState(initialMount),[depth,setDepth]=useState<HeroDepth>(initialDepth==='flat'?'floating':initialDepth),[mobile,setMobile]=useState(false),[replay,setReplay]=useState(0),[message,setMessage]=useState('');
 useEffect(()=>{dialog.current?.showModal();},[]);
 return <dialog ref={dialog} onCancel={e=>{e.preventDefault();onClose();}} aria-labelledby="studio-title" className="w-[min(920px,94vw)] max-h-[90vh] overflow-y-auto rounded-3xl border bg-[#fffaf7] p-6 shadow-xl backdrop:bg-black/40">
 <div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-widest text-muted-foreground">ShopFia · Preview</p><h2 id="studio-title" className="mt-2 text-2xl font-semibold">{intro?'Try 3D animations':'3D Studio'}</h2></div><button type="button" aria-label="Close 3D Studio" onClick={onClose} className="rounded-full border px-3 py-2">✕</button></div>
 {intro ? <div className="py-6"><p className="max-w-lg text-sm leading-6">Give {name || 'your storefront'} a little movement. Start with your logo, preview it, and choose whether to use it.</p><div className="mt-6 flex gap-3"><button type="button" onClick={()=>setIntro(false)} className="rounded-full bg-[#493e46] px-5 py-3 text-sm text-white">Explore 3D</button><button type="button" onClick={onClose} className="rounded-full border px-5 py-3 text-sm">Not now</button></div></div> : <>
 <div className="mt-5 flex flex-wrap gap-2" role="group" aria-label="3D creation mode">{(['suggest','describe'] as const).map(m=><button type="button" key={m} aria-pressed={mode===m} onClick={()=>setMode(m)} className="rounded-full border px-4 py-2 text-sm aria-pressed:bg-[#493e46] aria-pressed:text-white">{m==='suggest'?'Suggestions for my brand':'Describe my idea'}</button>)}</div>
 <div className="mt-5 grid gap-6 md:grid-cols-2"><div>
 {mode==='suggest'?<><h3 className="font-semibold">Start with your logo</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">These working presets use your current artwork and colors. They are not AI-generated.</p><div className="mt-4 grid grid-cols-3 gap-2">{(['artwork','round','square'] as const).map(m=><button type="button" key={m} aria-pressed={mount===m} onClick={()=>setMount(m)} className="rounded-xl border p-3 text-xs aria-pressed:bg-[#eee5e9]">{m==='artwork'?'Floating logo':m==='round'?'Round emblem':'Square badge'}</button>)}</div></>:<><label className="grid gap-2 text-sm font-medium">What would you like to create?<textarea value={brief} onChange={e=>{setBrief(e.target.value);setMessage('');}} placeholder="Describe your animation idea here" rows={4} className="rounded-xl border bg-white p-3 font-normal"/></label><p className="mt-2 text-xs leading-5 text-muted-foreground">AI generation isn’t connected in this preview. Your idea stays here while you explore the logo presets.</p><button type="button" disabled={!brief.trim()} onClick={()=>{onBriefChange(brief);setMessage('Idea kept for this session. The preview remains a logo preset; no custom animation has been generated.');}} className="mt-3 rounded-full border px-4 py-2 text-sm disabled:opacity-40">Keep this idea</button>{message&&<p role="status" className="mt-2 text-xs">{message}</p>}</>}
 <fieldset className="mt-6"><legend className="text-sm font-semibold">When it plays</legend><div className="mt-2 flex gap-2">{(['flat','floating','layered'] as const).map(d=><button type="button" key={d} aria-pressed={depth===d} onClick={()=>setDepth(d)} className="rounded-full border px-4 py-2 text-xs aria-pressed:bg-[#eee5e9]">{d==='flat'?'Off':d==='floating'?'Intro':'Exit'}</button>)}</div></fieldset><p className="mt-3 text-xs leading-5 text-muted-foreground">Booking stays available. Intro settles after a brief reveal; Exit plays as the hero scrolls away. Reduced-motion preferences are respected.</p>
 </div><div><div className="mb-2 flex justify-between gap-2"><div role="group" aria-label="Animation preview device">{[false,true].map(m=><button key={String(m)} type="button" aria-pressed={mobile===m} onClick={()=>setMobile(m)} className="rounded-full border px-3 py-1 text-xs aria-pressed:bg-[#eee5e9]">{m?'Mobile':'Desktop'}</button>)}</div><button type="button" onClick={()=>setReplay(v=>v+1)} className="text-xs underline">Replay</button></div><div className={`relative mx-auto h-72 overflow-hidden rounded-2xl bg-[#eee8e0] ${mobile?'max-w-[210px]':'w-full'}`}>{logo ? <StorefrontBrandSculpture key={`${mount}-${mobile}-${replay}`} image={logo} name={name} mount={mount} edgeColor={edgeColor} touchPreview={mobile} interactive={depth!=='flat'}/> : <p className="p-8 text-sm">Add your logo to preview a 3D effect.</p>}</div><p className="mt-2 text-xs text-muted-foreground">Logo-effect preview · timing is shown in your storefront after applying.</p></div></div>
 <div className="mt-6 flex justify-end gap-3 border-t pt-4"><button type="button" onClick={onClose} className="rounded-full border px-5 py-2 text-sm">Cancel</button><button type="button" disabled={!logo&&depth!=='flat'} onClick={()=>{onApply(depth,mount);onClose();}} className="rounded-full bg-[#493e46] px-5 py-2 text-sm text-white disabled:opacity-40">Apply to preview</button></div></>}
 </dialog>;
}
